// Canais monitorados — lista pública, edite aqui para adicionar/remover canais.
// Para descobrir o channelId (formato UC...): abra o canal no YouTube → aba
// "Sobre" → "Compartilhar canal" → "Copiar ID do canal".
const CANAIS = [
  { channelId: 'UC_SUBSTITUA_PELO_ID_REAL_1', channelName: 'Brian Pasch' },
  { channelId: 'UC_SUBSTITUA_PELO_ID_REAL_2', channelName: 'Autoline Network' },
];

// Janela de busca: 7 dias (semanal). Para bi-semanal, use 14 e ajuste o trigger.
const DIAS_JANELA = 7;

// Fail-fast: sem credenciais não há o que executar.
for (const nome of ['YOUTUBE_API_KEY', 'RAPIDAPI_KEY', 'TELEGRAM_BOT_TOKEN', 'TELEGRAM_CHAT_ID']) {
  if (!$env[nome]) {
    throw new Error('Variável de ambiente ausente no container n8n: ' + nome + ' (ver agents/youtube-etl/README.md)');
  }
}

const publishedAfter = new Date(Date.now() - DIAS_JANELA * 24 * 60 * 60 * 1000).toISOString();
return CANAIS.map((c) => ({ json: { ...c, publishedAfter } }));

// Achata as respostas da search.list em 1 item por vídeo.
// Canal com erro na API não derruba o run: vira entrada em `falhas`.
const videos = [];
const falhas = [];
const entradas = $input.all();

for (let i = 0; i < entradas.length; i++) {
  const r = entradas[i].json;
  const canal = $('Config Canais').itemMatching(i).json.channelName;
  if (r.error) {
    const detalhe = (r.error.message || JSON.stringify(r.error)).slice(0, 200);
    falhas.push(canal + ': erro na YouTube API — ' + detalhe);
    continue;
  }
  for (const v of r.items || []) {
    const videoId = v.id && v.id.videoId;
    if (!videoId) continue;
    videos.push({
      videoId,
      titulo: (v.snippet && v.snippet.title) || '(sem título)',
      canal: (v.snippet && v.snippet.channelTitle) || canal,
      publicadoEm: (v.snippet && v.snippet.publishedAt) || '',
    });
  }
}

if (videos.length === 0) {
  // Sentinela: mantém o fluxo vivo até o relatório/notificação de semana vazia.
  return [{ json: { semVideos: true, falhas } }];
}

videos[0].falhas = falhas;
return videos.map((v) => ({ json: v }));

const SYSTEM_PROMPT = [
  'Você é um Engenheiro de Dados e Estrategista de Mercado Automotivo.',
  'Sua tarefa é analisar a transcrição de um vídeo e extrair métricas e tendências críticas, descartando todo o ruído, opiniões não fundamentadas e introduções.',
  '',
  'Regras de Extração:',
  '1. Extraia apenas dados factuais relacionados a: Demanda global/regional, Incentivos/Subsídios, Números de vendas, e Métricas de Performance (CVR, CTR, CPA, margens).',
  '2. Se um dado ou métrica específica não for mencionado no texto fornecido, você DEVE retornar null. Não infira, não invente.',
  '3. Mantenha os resumos extremamente concisos (máximo de 2 frases por campo).',
  '',
  'Regra de Formatação (CRÍTICA):',
  'O seu output DEVE ser ÚNICA e EXCLUSIVAMENTE um objeto JSON válido. Não inclua nenhuma formatação markdown (como ```json), explicações, saudações ou texto antes ou depois do JSON.',
  '',
  'Estrutura obrigatória do JSON:',
  '{',
  '  "assunto_principal": "string",',
  '  "demanda_estoque": "string ou null",',
  '  "incentivos_subsidios": "string ou null",',
  '  "metricas_performance": {',
  '    "cvr_taxa_conversao": "string ou null",',
  '    "ctr_cliques": "string ou null",',
  '    "vendas_volume": "string ou null"',
  '  },',
  '  "insight_estrategico": "string (Apenas se houver uma oportunidade clara de produto ou negócio baseada nos dados)"',
  '}',
].join('\n');

// Margem confortável para OLLAMA_CONTEXT_LENGTH=65536 (~6k tokens de entrada).
const MAX_CHARS = 24000;

// Tolerante aos formatos de resposta mais comuns das APIs de transcript do
// RapidAPI: { transcript: [...] }, { data: [...] }, { text: '...' } etc.
function extrairTranscricao(j) {
  if (!j || j.error) return '';
  const cand = j.transcript ?? j.data ?? j.text ?? j.content ?? null;
  if (typeof cand === 'string') return cand.trim();
  if (Array.isArray(cand)) {
    return cand
      .map((t) => (typeof t === 'string' ? t : (t && (t.text || t.snippet)) || ''))
      .join(' ')
      .trim();
  }
  return '';
}

const entradas = $input.all();
const saida = [];
const semTranscricao = [];
let falhas = [];
let semVideos = false;

for (let i = 0; i < entradas.length; i++) {
  const origem = $('Extrair VideoIds').itemMatching(i).json;
  if (origem.falhas) falhas = origem.falhas;
  if (origem.semVideos) {
    semVideos = true;
    continue;
  }

  const transcricao = extrairTranscricao(entradas[i].json);
  if (!transcricao) {
    semTranscricao.push(origem.canal + ': "' + origem.titulo + '" (https://youtu.be/' + origem.videoId + ')');
    continue;
  }

  saida.push({
    json: {
      videoId: origem.videoId,
      titulo: origem.titulo,
      canal: origem.canal,
      publicadoEm: origem.publicadoEm,
      ollamaBody: JSON.stringify({
        model: 'llama3.2',
        stream: false,
        format: 'json', // força a API do Ollama a emitir JSON válido
        options: { temperature: 0.2 },
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: 'TRANSCRIÇÃO DO VÍDEO "' + origem.titulo + '" (canal ' + origem.canal + '):\n\n' + transcricao.slice(0, MAX_CHARS) },
        ],
      }),
    },
  });
}

if (saida.length === 0) {
  // Semana sem nada analisável: chamada mínima ao Ollama só para manter o fluxo
  // linear vivo até o relatório/notificação (custo local desprezível).
  saida.push({
    json: {
      pularAnalise: true,
      ollamaBody: JSON.stringify({
        model: 'llama3.2',
        stream: false,
        format: 'json',
        options: { num_predict: 5 },
        messages: [{ role: 'user', content: 'Responda apenas {}' }],
      }),
    },
  });
}

saida[0].json.semTranscricao = semTranscricao;
saida[0].json.falhas = falhas;
saida[0].json.semVideos = semVideos;
return saida;

const CAMPOS_TEXTO = ['demanda_estoque', 'incentivos_subsidios'];
const CAMPOS_METRICAS = ['cvr_taxa_conversao', 'ctr_cliques', 'vendas_volume'];

function validarSchema(obj) {
  const erros = [];
  if (typeof obj.assunto_principal !== 'string' || !obj.assunto_principal.trim()) {
    erros.push('assunto_principal ausente ou vazio');
  }
  for (const campo of CAMPOS_TEXTO) {
    if (obj[campo] !== null && obj[campo] !== undefined && typeof obj[campo] !== 'string') {
      erros.push(campo + ' deve ser string ou null');
    }
  }
  const mp = obj.metricas_performance;
  if (!mp || typeof mp !== 'object' || Array.isArray(mp)) {
    erros.push('metricas_performance ausente ou inválido');
  } else {
    for (const campo of CAMPOS_METRICAS) {
      if (mp[campo] !== null && mp[campo] !== undefined && typeof mp[campo] !== 'string') {
        erros.push('metricas_performance.' + campo + ' deve ser string ou null');
      }
    }
  }
  if (obj.insight_estrategico !== null && obj.insight_estrategico !== undefined && typeof obj.insight_estrategico !== 'string') {
    erros.push('insight_estrategico deve ser string');
  }
  return erros;
}

const entradas = $input.all();
const saida = [];

for (let i = 0; i < entradas.length; i++) {
  const origem = $('Montar Prompt Ollama').itemMatching(i).json;
  const meta = {
    videoId: origem.videoId,
    titulo: origem.titulo,
    canal: origem.canal,
    publicadoEm: origem.publicadoEm,
    pularAnalise: origem.pularAnalise || false,
    semTranscricao: origem.semTranscricao,
    falhas: origem.falhas,
    semVideos: origem.semVideos,
  };

  if (meta.pularAnalise) {
    saida.push({ json: { ...meta, ok: false } });
    continue;
  }

  const bruto = entradas[i].json.message && entradas[i].json.message.content;
  if (!bruto) {
    const detalhe = JSON.stringify(entradas[i].json).slice(0, 200);
    saida.push({ json: { ...meta, ok: false, erro: 'Ollama não retornou conteúdo (' + detalhe + ')' } });
    continue;
  }

  // Mesmo com format:json, remove cercas markdown defensivamente.
  const limpo = bruto.replace(/```(?:json)?/g, '').trim();
  let analise;
  try {
    analise = JSON.parse(limpo);
  } catch (e) {
    saida.push({ json: { ...meta, ok: false, erro: 'JSON inválido: ' + e.message, bruto: limpo.slice(0, 500) } });
    continue;
  }

  const errosSchema = validarSchema(analise);
  if (errosSchema.length > 0) {
    saida.push({ json: { ...meta, ok: false, erro: 'Schema inválido: ' + errosSchema.join('; '), bruto: limpo.slice(0, 500) } });
    continue;
  }

  saida.push({ json: { ...meta, ok: true, analise } });
}

return saida;

const dataStr = new Date().toISOString().slice(0, 10);
const itens = $input.all().map((i) => i.json);
const meta = itens[0];
const analises = itens.filter((i) => i.ok);
const invalidos = itens.filter((i) => !i.ok && !i.pularAnalise);
const semTranscricao = meta.semTranscricao || [];
const falhas = meta.falhas || [];

const linhas = [];
linhas.push('# YouTube ETL — Mercado Automotivo — ' + dataStr);
linhas.push('');
linhas.push('Análise semanal de transcrições via Ollama (llama3.2).');
linhas.push('');

if (analises.length === 0) {
  linhas.push(meta.semVideos
    ? 'Nenhum vídeo novo encontrado nos canais monitorados no período.'
    : 'Nenhuma análise válida gerada no período (ver rodapé de execução).');
  linhas.push('');
}

const porCanal = {};
for (const a of analises) {
  (porCanal[a.canal] = porCanal[a.canal] || []).push(a);
}
for (const canal of Object.keys(porCanal).sort()) {
  linhas.push('## ' + canal);
  linhas.push('');
  for (const a of porCanal[canal]) {
    const m = a.analise.metricas_performance || {};
    linhas.push('### ' + a.titulo);
    linhas.push('');
    linhas.push('- **Vídeo:** https://youtu.be/' + a.videoId + (a.publicadoEm ? ' (' + a.publicadoEm.slice(0, 10) + ')' : ''));
    linhas.push('- **Assunto principal:** ' + a.analise.assunto_principal);
    linhas.push('- **Demanda/estoque:** ' + (a.analise.demanda_estoque ?? '—'));
    linhas.push('- **Incentivos/subsídios:** ' + (a.analise.incentivos_subsidios ?? '—'));
    linhas.push('- **CVR (taxa de conversão):** ' + (m.cvr_taxa_conversao ?? '—'));
    linhas.push('- **CTR (cliques):** ' + (m.ctr_cliques ?? '—'));
    linhas.push('- **Vendas/volume:** ' + (m.vendas_volume ?? '—'));
    if (a.analise.insight_estrategico) {
      linhas.push('- **Insight estratégico:** ' + a.analise.insight_estrategico);
    }
    linhas.push('');
  }
}

linhas.push('---');
linhas.push('');
linhas.push('## Execução');
linhas.push('');
linhas.push('- Vídeos analisados: ' + analises.length);
linhas.push('- Sem transcrição disponível: ' + semTranscricao.length);
linhas.push('- Análises com JSON/schema inválido: ' + invalidos.length);
linhas.push('- Falhas de API: ' + falhas.length);
for (const s of semTranscricao) linhas.push('  - Sem transcrição — ' + s);
for (const inv of invalidos) linhas.push('  - Inválido — ' + (inv.canal || '?') + ': "' + (inv.titulo || '?') + '" (' + (inv.erro || '') + ')');
for (const f of falhas) linhas.push('  - Falha — ' + f);

const md = linhas.join('\n') + '\n';
const fileName = dataStr + '-youtube-etl.md';

// Resumo para o Telegram (limite da API: 4096 chars).
const resumoLinhas = ['YouTube ETL — ' + dataStr, ''];
if (analises.length === 0) {
  resumoLinhas.push('Nenhuma análise nova esta semana' + (meta.semVideos ? ' (sem vídeos novos)' : '') + '.');
} else {
  for (const a of analises) {
    resumoLinhas.push('• [' + a.canal + '] ' + a.titulo);
    resumoLinhas.push('  ' + a.analise.assunto_principal);
    if (a.analise.insight_estrategico) resumoLinhas.push('  Insight: ' + a.analise.insight_estrategico);
  }
}
resumoLinhas.push('');
resumoLinhas.push('Relatório completo: agents/youtube-etl/reports/' + fileName);
let resumo = resumoLinhas.join('\n');
if (resumo.length > 4000) resumo = resumo.slice(0, 4000) + '…';

return [{
  json: {
    filePath: '/data/youtube-etl/reports/' + fileName,
    fileName,
    telegramBody: JSON.stringify({ chat_id: $env.TELEGRAM_CHAT_ID, text: resumo }),
  },
  binary: {
    data: {
      data: Buffer.from(md, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName,
    },
  },
}];
